head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.screenId = "jldfil30700";
scwin.i = null;
scwin.j = null;

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function () {
    try {
        scwin.init_recvParam();
        scwin.init_rowCopy();
        scwin.init_attrReals();
        await scwin.init_loadList();
    } catch (e) {
        await $c.exception.handleError(e, { context: 'jldfil30700.onpageload' });
    }
};

/**
 * @method
 * @name init_attrReals
 * @description 속성 실현 — as-is EL 이 그리던 안내 문구·속성을 컨텍스트 값으로 반영(진입 1회·데이터 재적재 시 재호출)
 * @returns {void}
 * @hidden N
 */
scwin.init_attrReals = function () {
    const attrRealsList = [{ childId: "rd_raChrgNm", attr: "__items", fn: function () { return [[String(dma_chrgInfoVO.get("disclsChrgNm1")), String(dma_chrgInfoVO.get("disclsChrgNm1")) + " (" + String(dma_chrgInfoVO.get("cellPhoneNo1")) + ")"], [String(dma_chrgInfoVO.get("disclsChrgNm2")), String(dma_chrgInfoVO.get("disclsChrgNm2")) + " (" + String(dma_chrgInfoVO.get("cellPhoneNo2")) + ")"]]; } },
        { childId: "rd_empNm", attr: "__items", fn: function () { return [[String(dma_chrgInfoVO.get("rcvrEmpNo")), String(dma_chrgInfoVO.get("empNm"))], ["2", ""]]; } }];
    attrRealsList.forEach(function (a) {
        const comp = $c.util.getComponent(a.childId);
        if (!comp) { return; }
        let v;
        try { v = a.fn(); } catch (e) { $c.exception.handleError(e, { notify: "none", context: "attrReal:" + a.childId }); return; }
        if (a.attr === "style") {
            String(v).split(";").forEach(function (decl) {
                const kv = decl.split(":");
                if (kv.length === 2 && kv[0].trim()) { comp.setStyle(kv[0].trim(), kv[1].trim()); }
            });
        } else if (a.attr === "label" || a.attr === "__value") {
            if (typeof comp.setValue === "function") { comp.setValue(v); } else if (comp.render) { comp.render.textContent = v; }
        } else if (a.attr === "__items") {
            if (typeof comp.addItem === "function" && v && v.length) {
                if (typeof comp.removeAll === "function") { comp.removeAll(); }
                v.forEach(function (it) { comp.addItem(String(it[0] || ""), String(it[1] || "")); });
            }
        } else if (a.attr === "class") {
            if (comp.render) { comp.render.className = v; }
        } else if (a.attr === "__html") {
            if (comp.render) { comp.render.innerHTML = v; }
        } else if (comp.render) {
            comp.render.setAttribute(a.attr, v);
        }
    });
};

/**
 * @method
 * @name init_rowCopy
 * @description dataList 단건 표시 복사 — 진입점에서 1회. 데이터 재적재 시 ev:ondataload 가 다시 부른다.
 * @returns {void}
 * @hidden N
 */
scwin.init_rowCopy = function () {
    const rows = [{ childId: "__rb0", fn: function () { return String((($c.session && $c.session.getUserInfo && $c.session.getUserInfo()) || {})["comAbbrv"] ?? ""); } }];
    rows.forEach(function (it) {
        const c = $c.util.getComponent(it.childId);
        if (!c || typeof c.setValue !== "function") { return; }  // as-is 가 서버 렌더로 그리던 반복 행 — 산출에 없는 칸은 건너뛴다
        let v;
        try { v = it.fn(); } catch (e) { $c.exception.handleError(e, { notify: "none", context: "rowCopy:" + it.childId }); return; }
        if (v !== undefined && v !== null && String(v).trim() !== "") { c.setValue(String(v)); }
    });
};

/**
 * @method
 * @name init_loadList
 * @description 초기 목록 조회 — as-is 는 진입 자체가 조회였다
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.init_loadList = async function () {
    // 초기 목록 — as-is 는 진입 자체가 조회였다(근거: self_submit). 진입점 합성이 이 단계를 잇는다.
    await scwin.tx_fn_send();
};

/**
 * @method
 * @name init_recvParam
 * @description 화면 전환 파라미터 수신 — $c.data.getParameter() 를 dma_pageContext 에 담는다
 * @returns {void}
 * @hidden N
 */
scwin.init_recvParam = function () { dma_pageContext.setJSON($c.data.getParameter() ?? {}); };

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name rd_raChrgNm_onclick
 * @description rd_raChrgNm 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.rd_raChrgNm_onclick = function(e){
    try {
        scwin.another('__self.value')

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldfil30700.rd_raChrgNm_onclick' }); }
};

/**
 * @method
 * @name ipt_name3_onclick
 * @description 「3」 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.ipt_name3_onclick = function(e){
    try {
        scwin.another('__self.value')

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldfil30700.ipt_name3_onclick' }); }
};

/**
 * @method
 * @name rd_empNm_onclick
 * @description rd_empNm 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.rd_empNm_onclick = function(e){
    try {
        scwin.fnRcvrEmpChk()

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldfil30700.rd_empNm_onclick' }); }
};

/**
 * @method
 * @name btn_send_onclick
 * @description btn_send 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_send_onclick = async function(e){
    try {
        await scwin.send()

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldfil30700.btn_send_onclick' }); }
};

///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name tx_fn_send
 * @description send 서버 호출
 * @param {*} action 제출 주소(호출부가 as-is form.action 으로 정하던 분기별 URL · 생략 시 기본 주소)
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_fn_send = async function (action) {
    const sbmOptions = {
        id: "tx_fn_send",
        method: "post",
        action: action ?? "/issue/smsSend.do",
        ref: "dma_sendReq",
        target: "dlt_teamInfoVO=body.content",
        isProcessMsg: false
    };
    const res = await $c.sbm.executeDynamic(sbmOptions);
    if (res && res.skipped) { return res; }  // 중복 제출 skip
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
    }
    return res;
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name tx_fn_chkChrgWork_xhr
 * @description chk Chrg Work xhr 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_fn_chkChrgWork_xhr = async function () {
    // ⛔주소가 없다 — as-is 는 «자기 자신» 에게 제출했는데(`self_submit`) 화면 자신의 액션 URL 을
    //   하나로 못 정했다(후보 0 또는 여럿). 빈 주소로 내보내면 «조용히 엉뚱한 곳» 이다.
    // TODO Stage2: 전환 미완(공급사 드러냄 — 사유 알림 유지) "이 화면의 제출 주소를 아직 정하지 못했습니다(전환 미완) — tx_fn_chkChrgWork_xhr"
    throw { bizMessage: "이 화면의 제출 주소를 아직 정하지 못했습니다(전환 미완) — tx_fn_chkChrgWork_xhr", unresolved: "action:self_submit:tx_fn_chkChrgWork_xhr" };
};

/**
 * @method
 * @name send
 * @description send 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.send = async function () {
    const frm = (document.smsSendForm || { elements: [] });
    let raChargNmSelFlag = "N";
    if (frm.raChrgNm[2].checked) {
        raChargNmSelFlag = "Y";
        if (await $c.fil.checkRequired($c.util.getComponent('ipt_inChrgNm'))) {
            return;
        }
        if (await $c.fil.checkRequired($c.util.getComponent('ipt_cellphoneNo2')) || await $c.fil.checkRequired($c.util.getComponent('ipt_cellphoneNo3'))) {
            return;
        }
        if (!($c.fil.isNumberInput($c.util.getComponent('slc_cellphoneNo1')) && $c.fil.isNumberInput($c.util.getComponent('ipt_cellphoneNo2')) && $c.fil.isNumberInput($c.util.getComponent('ipt_cellphoneNo3')))) {
            await $c.win.alert("'휴대전화번호' 항목은 숫자만 입력하세요");
            return;
        }
        $c.util.getComponent('dma_sendReq').set('chrgNm', $c.util.getComponent('ipt_inChrgNm').getValue());
        $c.util.getComponent('dma_sendReq').set('cellPhoneNo', $c.util.getComponent('slc_cellphoneNo1').getValue()+ '-' + $c.util.getComponent('ipt_cellphoneNo2').getValue()+ '-' + $c.util.getComponent('ipt_cellphoneNo3').getValue());
    } else {
        for (scwin.i = 0; scwin.i < 2; scwin.i++) {
            if ($c.util.getComponent('rd_raChrgNm')[scwin.i].checked) {
                raChargNmSelFlag = "Y";
                if (frm.raCellPhoneNo[scwin.i].value === "" || frm.raCellPhoneNo[scwin.i].value == null) {
                    await $c.win.alert("『정보관리 > 공시관리자정보 > 공시담당자정보』메뉴에서 연락처를 수정하세요");
                    return;
                }
                $c.util.getComponent('dma_sendReq').set('chrgNm', $c.util.getComponent('rd_raChrgNm')[scwin.i].value);
                $c.util.getComponent('dma_sendReq').set('cellPhoneNo', frm.raCellPhoneNo[scwin.i].value);
                break;
            }
        }
    }
    if (raChargNmSelFlag === "N") {
        await $c.win.alert("'발신자' 항목을 선택하세요");
        return;
    }
    for (scwin.i = 0; scwin.i < $c.util.getComponent('rd_empNm').length; scwin.i++) {
        if ($c.util.getComponent('rd_empNm')[scwin.i].checked) {
            const obj = $c.util.getComponent('rd_empNm')[scwin.i];
            const selNo = $c.util.getComponent('rd_empNm')[scwin.i].value;
            if (selNo != null && selNo !== "2") {
                $c.util.getComponent('dma_sendReq').set('rcvrEmpNo', obj.getValue());
            } else {
                const empList = $c.util.getComponent('slc_empNm2');
                for (scwin.j = 0; scwin.j < empList.length; scwin.j++) {
                    if (empList[scwin.j].selected) {
                        $c.util.getComponent('dma_sendReq').set('rcvrEmpNo', empList[scwin.j].value);
                    }
                }
            }
        }
    }
    if (await $c.win.confirm('전송하시겠습니까?')) {
        $c.util.getComponent('dma_sendReq').set('method', 'smsSend');
        await scwin.tx_fn_send('smsSend.do');
    }
};

/**
 * @method
 * @name another
 * @description another 처리
 * @param {*} val val
 * @returns {void}
 * @hidden N
 */
scwin.another = function (val) {
    const divObj = $c.util.getComponent("anotherSender");
    if (val === '3') {
        (!divObj ? console.warn('[sdd] 표시 전환 대상 미해결: divObj') : (('block') === 'none' ? (divObj.hide ? divObj.hide() : void 0) : (divObj.show ? divObj.show() : void 0)));
    } else {
        (!divObj ? console.warn('[sdd] 표시 전환 대상 미해결: divObj') : (('none') === 'none' ? (divObj.hide ? divObj.hide() : void 0) : (divObj.show ? divObj.show() : void 0)));
    }
    $c.util.getComponent('dma_sendReq').set('chrgNm', "");
};

/**
 * @method
 * @name chkChrgWork
 * @description chk Chrg Work 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.chkChrgWork = async function () {
    (document.smsSendForm || { elements: [] }).action = "/issue/smsSend.do";
    $c.util.getComponent('dma_sendReq').set('method', "chrgWorkYn");
    await scwin.tx_fn_chkChrgWork_xhr();
};

/**
 * @method
 * @name onCompleteResponse
 * @description on Complete Response 처리
 * @param {*} responseXML responseXML
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onCompleteResponse = async function (responseXML) {
    if ((responseXML == null) || ('' === responseXML)) {
        await $c.win.alert("데이터를 불러올 수 없습니다.");
    } else {
        const xmlDoc = xmlHttp.responseXML;
        const chkSubstituteInfo = xmlDoc.getElementsByTagName("chkSubstituteInfo")[0];
        let chrgWorkYn = "";
        const chrgNm = "";
        const toDate = "";
        const substituteInfo = "";
        if (chkSubstituteInfo != null) {
            chrgWorkYn = chkSubstituteInfo.getElementsByTagName("result")[0].firstChild.nodeValue;
        }
        if (chrgWorkYn === 'N') {
            $("input:radio[name='empNm']").eq(0).attr("checked", "false");
            $("input:radio[name='empNm']").eq(0).attr("disabled", "true");
            $("input:radio[name='empNm']").eq(1).attr("checked", "false");
        } else {
            $("input:radio[name='empNm']").eq(0).attr("checked", "true");
            (($c.util.getComponent('slc_empNm2')) && ($c.util.getComponent('slc_empNm2')).setDisabled ? ($c.util.getComponent('slc_empNm2')).setDisabled((("true") === '' || ("true") === false || ("true") === 'false') ? false : ((("true") === true || ("true") === 'true' || ("true") === 'disabled') ? true : ("true"))) : void 0);
        }
    }
};

/**
 * @method
 * @name fnRcvrEmpChk
 * @description fn Rcvr Emp Chk 처리
 * @returns {void}
 * @hidden N
 */
scwin.fnRcvrEmpChk = function () {
    const rcvrEmp = $("input:radio[name='empNm']");
    if (rcvrEmp.eq(0).is(':checked')) {
        (($c.util.getComponent('slc_empNm2')) && ($c.util.getComponent('slc_empNm2')).setDisabled ? ($c.util.getComponent('slc_empNm2')).setDisabled((("true") === '' || ("true") === false || ("true") === 'false') ? false : ((("true") === true || ("true") === 'true' || ("true") === 'disabled') ? true : ("true"))) : void 0);
    } else {
        $c.util.getComponent("slc_empNm2").setDisabled(false);
    }
};
